<template><view class="page"><view class="head"><view><text class="eyebrow">MY LITTLE DESK</text><text class="title">我的日记桌面</text></view><view class="new" @click="openToday">＋ 写今天</view></view><text class="tip">每一天，都是一个可以打开的小房间</text><view class="month"><text>{{monthLabel}}</text><text>{{entries.length}} 篇日记</text></view><scroll-view scroll-y class="scroll"><view class="grid"><view class="folder" v-for="item in entries" :key="item.date" @click="open(item.date)"><view class="folder-box"><view class="tab"></view><text>{{item.hasContent?'✦':'·'}}</text></view><text>{{item.date}}</text><text class="state">{{item.hasContent?'已记录':'空白页'}}</text></view><view class="folder" @click="pickDate"><view class="folder-box add">＋</view><text>新建日期</text></view></view></scroll-view><view v-if="book" class="mask" @click="close"><view class="book" @click.stop><view v-if="!reading" class="cover"><text>MY DIARY</text><text class="cover-date">{{date}}</text><view class="open" @click="reading=true">打开日记本</view></view><view v-else class="inside"><view class="bar"><text>{{date}}</text><text @click="close">合上</text></view><view class="quads"><view class="quad" v-for="s in sections" :key="s.key" @click="edit(s.key)"><text class="qt">{{s.title}}</text><text class="qp">{{note[s.key]||'点击写下今天的记录…'}}</text><text class="pen">✎</text></view></view><view class="save" @click="save">{{saved?'已保存':'保存今天'}}</view></view></view></view><view v-if="editing" class="mask" @click="editing=''" ><view class="editor" @click.stop><text class="et">{{sectionTitle}}</text><textarea v-model="draft" auto-height maxlength="1000" placeholder="写下你想记住的事情…"/><view class="actions"><text @click="editing=''">取消</text><text class="done" @click="finish">完成</text></view></view></view><view v-if="picker" class="mask" @click="picker=false"><view class="editor" @click.stop><text class="et">选择日记日期</text><picker mode="date" :value="pick" @change="pick=$event.detail.value"><view class="date">{{pick}}　点击选择</view></picker><view class="actions"><text @click="picker=false">取消</text><text class="done" @click="open(pick);picker=false">打开</text></view></view></view></view></template>
<script>
const KEY='fourPartDiaries';const blank=()=>({food:'',timeline:'',thoughts:'',gratitude:''});export default{data(){return{entries:[],date:'',note:blank(),book:false,reading:false,editing:'',draft:'',saved:false,picker:false,pick:this.f(new Date()),sections:[{key:'food',title:'吃了什么'},{key:'timeline',title:'时间轴'},{key:'thoughts',title:'碎碎念'},{key:'gratitude',title:'感恩'}]}},computed:{monthLabel(){return this.date?this.date.slice(0,7).replace('-',' 年 ')+' 月':'我的日记'},sectionTitle(){let s=this.sections.find(x=>x.key===this.editing);return s?s.title:''}},onShow(){this.load()},methods:{f(d){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},load(){let a=uni.getStorageSync(KEY)||{};this.entries=Object.keys(a).sort().reverse().map(date=>({date,hasContent:Object.values(a[date]||{}).some(Boolean)}))},openToday(){this.open(this.f(new Date()))},pickDate(){this.pick=this.f(new Date());this.picker=true},open(date){let a=uni.getStorageSync(KEY)||{};this.date=date;this.note={...blank(),...(a[date]||{})};this.book=true;this.reading=false;this.saved=false},close(){this.book=false;this.editing='';this.load()},edit(k){this.editing=k;this.draft=this.note[k]||''},finish(){this.note[this.editing]=this.draft;this.editing='';this.saved=false},save(){let a=uni.getStorageSync(KEY)||{};a[this.date]={...blank(),...this.note,updatedAt:Date.now()};uni.setStorageSync(KEY,a);this.saved=true;this.load()}}}
</script>
<style lang="scss" scoped>
.page{min-height:100vh;background:linear-gradient(#3988d5 0,#65a7df 38%,#f4ead8 38%);padding:56rpx 28rpx 140rpx}.head{display:flex;justify-content:space-between;align-items:end;color:#fff}.eyebrow{display:block;font-size:20rpx;letter-spacing:4rpx;opacity:.8}.title{display:block;font-size:44rpx;font-weight:700;margin-top:10rpx}.new{background:#fff;color:#287bc2;border-radius:28rpx;padding:14rpx 22rpx;font-size:24rpx}.tip{display:block;color:#eaf5ff;font-size:24rpx;margin:22rpx 0 34rpx}.month{background:#fff8;border-radius:22rpx;padding:18rpx 22rpx;color:#fff;display:flex;justify-content:space-between}.scroll{height:calc(100vh - 270rpx);margin-top:28rpx}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:34rpx 18rpx}.folder{text-align:center;color:#314b65;font-size:22rpx}.folder-box{height:118rpx;background:#ffdc68;border-radius:12rpx 16rpx 14rpx 14rpx;position:relative;box-shadow:0 8rpx 10rpx #82682c33;font-size:46rpx;line-height:118rpx;color:#fff2a9}.tab{position:absolute;top:-10rpx;left:12rpx;width:62rpx;height:24rpx;background:#ffe994;border-radius:12rpx 12rpx 0 0}.state{display:block;font-size:18rpx;color:#7890a5;margin-top:8rpx}.add{background:#ffffff55;border:2rpx dashed #fff;color:#fff}.mask{position:fixed;inset:0;background:#14263bbd;z-index:20;display:flex;align-items:center;justify-content:center;padding:30rpx}.book{width:100%;min-height:850rpx;background:#f7efde;border-radius:18rpx;overflow:hidden;animation:open .45s ease}.cover{min-height:850rpx;background:linear-gradient(135deg,#b96e4b,#e1a66e);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:28rpx;letter-spacing:5rpx}.cover-date{font-size:60rpx;font-weight:700;margin:32rpx 0}.open,.save{background:#a9684d;color:#fff;padding:18rpx 30rpx;border-radius:28rpx;font-size:26rpx;letter-spacing:0}.inside{padding:30rpx;background:repeating-linear-gradient(0deg,#f8f0df 0,#f8f0df 48rpx,#eee2cc 49rpx)}.bar,.actions{display:flex;justify-content:space-between;align-items:center;color:#8f6049}.bar{font-size:34rpx;font-weight:700}.quads{display:grid;grid-template-columns:1fr 1fr;gap:18rpx;margin-top:28rpx}.quad{min-height:270rpx;background:#fff9;padding:24rpx;border-radius:16rpx;box-shadow:inset 0 0 0 2rpx #decdb6;position:relative}.qt{display:block;font-size:28rpx;font-weight:700;color:#8f6049;border-bottom:2rpx solid #e7d5be;padding-bottom:12rpx}.qp{display:block;color:#66574e;font-size:25rpx;line-height:1.65;margin-top:16rpx;word-break:break-all}.pen{position:absolute;right:18rpx;bottom:12rpx;color:#c28a68}.save{margin:24rpx auto 0;width:max-content}.editor{width:100%;background:#fff8ee;border-radius:24rpx;padding:34rpx;box-sizing:border-box}.et{display:block;font-size:36rpx;color:#694d3f;font-weight:700;margin-bottom:22rpx}.editor textarea{width:100%;min-height:300rpx;background:#fff;border-radius:16rpx;padding:22rpx;font-size:30rpx;box-sizing:border-box}.actions{justify-content:flex-end;gap:28rpx;margin-top:26rpx;font-size:28rpx}.done{background:#a9684d;color:#fff;padding:14rpx 28rpx;border-radius:28rpx}.date{background:#fff;padding:26rpx;border-radius:14rpx;color:#765846;font-size:30rpx}@keyframes open{0%{transform:perspective(900px) rotateY(-70deg);opacity:.5}100%{transform:rotateY(0);opacity:1}}
</style>


